practice.solution:
#include <string>

std::string ascending(int n)
{
    std::string result;
    for (int i{1}; i <= n; ++i)
        result += std::to_string(i) + ' ';
    return result;
}

std::string countdown(int n)
{
    std::string result;
    for (int i{n}; i > 0; --i)
        result += std::to_string(i) + ' ';
    return result + "Launch!";
}

int main()
{
    return 0;
}

