#include <string>

std::string launchMessage(char permission)
{
    std::string message;
    if (permission == 'y')
    {
        message += "Preparing\n";
        message += "Simulated launch\n";
    }
    return message;
}

int main()
{
    return 0;
}

practice.tests:
#define main learner_main
#include "main.cpp"
#undef main
#include <iostream>

int main()
{
    if (launchMessage('y') != "Preparing\nSimulated launch\n")
    {
        std::cerr << "Authorized path must contain both messages in order\n";
        return 1;
    }
    for (char rejected : {'n', 'Y', 'x', ' ', '\0'})
    {
        if (!launchMessage(rejected).empty())
        {
            std::cerr << "Rejected permission must produce no message\n";
            return 1;
        }
    }
    return 0;
}
